1	import prisma from 'prisma/prisma';
2	import {
3	    OutcomeWhereUniqueInputObjectSchema,
4	    PlayerResponseSchema,
5	    TeamName,
6	    TeamNameSchema,
7	} from 'prisma/zod/schemas';
8	import { OutcomeType } from 'prisma/zod/schemas/models/Outcome.schema';
9	import z from 'zod';
10	
11	import { InternalError } from '@/lib/errors';
12	import { getPlayerPoints, isGame } from '@/lib/gameResult';
13	import { isPrismaNotFoundError } from '@/lib/prismaErrors';
14	import gameDayService from '@/services/GameDay';
15	import {
16	    PlayerFormType,
17	    TeamPlayerSchema,
18	    type TeamPlayerType,
19	    Turnout,
20	    TurnoutByYearType,
21	    WDLType,
22	} from '@/types';
23	import { OutcomePlayerType } from '@/types/OutcomePlayerType';
24	import {
25	    OutcomeCreateOneStrictSchema,
26	    OutcomeUpsertOneStrictSchema,
27	    type OutcomeWriteInput,
28	    OutcomeWriteInputSchema,
29	} from '@/types/OutcomeStrictSchema';
30	import type { PointsValue } from '@/types/Points';
31	
32	/** Linear merge of two PlayerFormType arrays already sorted by date then id. */
33	function mergeByDate(
34	    a: PlayerFormType[],
35	    b: PlayerFormType[],
36	): PlayerFormType[] {
37	    const result: PlayerFormType[] = [];
38	    let i = 0;
39	    let j = 0;
40	    while (i < a.length && j < b.length) {
41	        const dateDiff =
42	            a[i].gameDay!.date.getTime() - b[j].gameDay!.date.getTime();
43	        if (
44	            dateDiff < 0 ||
45	            (dateDiff === 0 && a[i].gameDay!.id <= b[j].gameDay!.id)
46	        ) {
47	            result.push(a[i++]);
48	        } else {
49	            result.push(b[j++]);
50	        }
51	    }
52	    while (i < a.length) result.push(a[i++]);
53	    while (j < b.length) result.push(b[j++]);
54	    return result;
55	}
56	
57	class OutcomeService {
58	    /**
59	     * Retrieves an Outcome for the given Player ID for the given GameDay ID.
60	     * @param gameDayId - The ID of the GameDay.
61	     * @param playerId - The ID of the Player.
62	     * @returns A promise that resolves to the Outcome if found, otherwise null.
63	     * @throws An error if there is a failure.
64	     */
65	    async get(
66	        gameDayId: number,
67	        playerId: number,
68	    ): Promise<OutcomeType | null> {
69	        const where = OutcomeWhereUniqueInputObjectSchema.parse({
70	            gameDayId_playerId: {
71	                gameDayId: gameDayId,
72	                playerId: playerId,
73	            },
74	        });
75	
76	        return prisma.outcome.findUnique({ where });
77	    }
78	
79	    /**
80	     * Retrieves all outcomes.
81	     * @returns A promise that resolves to an array of outcomes.
82	     */
83	    async getAll(): Promise<OutcomeType[]> {
84	        return prisma.outcome.findMany({});
85	    }
86	
87	    /**
88	     * Retrieves the last played outcome.
89	     * @returns A Promise that resolves to the last played Outcome, or null if no outcome is found.
90	     */
91	    async getLastPlayed(): Promise<OutcomeType | null> {
92	        return prisma.outcome.findFirst({
93	            where: {
94	                team: { not: null },
95	                gameDay: { status: { in: ['AWin', 'BWin', 'Draw'] } },
96	            },
97	            orderBy: {
98	                gameDayId: 'desc',
99	            },
100	        });
101	    }
102	
103	    /**
104	     * Retrieves all the outcomes for gameDays in a given year, or all years if
105	     * `year` is zero.
106	     * @param year - The year to include, or zero for all year.
107	     * @param untilGameDay - The gameDay ID to stop at (inclusive), or undefined
108	     * to include all.
109	     * @returns A promise that resolves to an array of Outcomes sorted by
110	     * gameDay, most recent first.
111	     * @throws An error if there is a failure.
112	     */
113	    async getAllForYear(
114	        year: number,
115	        untilGameDay?: number,
116	    ): Promise<OutcomeType[]> {
117	        return prisma.outcome.findMany({
118	            where: {
119	                gameDay: {
120	                    date:
121	                        year !== 0
122	                            ? {
123	                                  gte: new Date(Date.UTC(year, 0, 1)),
124	                                  lt: new Date(Date.UTC(year + 1, 0, 1)),
125	                              }
126	                            : {},
127	                    id: untilGameDay
128	                        ? {
129	                              lte: untilGameDay,
130	                          }
131	                        : {},
132	                },
133	            },
134	            orderBy: {
135	                gameDayId: 'desc',
136	            },
137	        });
138	    }
139	
140	    /**
141	     * Retrieves the response counts for a specific game day or all game days.
142	     *
143	     * @param gameDayId - Optional. The ID of the game day to retrieve response counts for.
144	     * @returns An array of game days with their corresponding response counts.
145	     * @throws If there is an error fetching the outcomes.
146	     */
147	    async getResponseCounts(gameDayId?: number) {
148	        return prisma.outcome.groupBy({
149	            orderBy: {
150	                gameDayId: 'asc',
151	            },
152	            where: {
153	                ...(gameDayId ? { gameDayId: gameDayId } : {}),
154	            },
155	            by: ['response', 'gameDayId'],
156	            _count: {
157	                response: true,
158	                team: true,
159	            },
160	        });
161	    }
162	
163	    /**
164	     * Retrieves the turnout for a specific game day or all game days.
165	     *
166	     * @param gameDayId - Optional. The ID of the game day to retrieve turnout for.
167	     * @returns An array of game days with their corresponding response counts.
168	     * @throws If there is an error fetching the outcomes.
169	     */
170	    async getTurnout(gameDayId?: number): Promise<Turnout[]> {
171	        const responseCounts = await this.getResponseCounts(gameDayId);
172	
173	        let gameDays = [];
174	        if (gameDayId === undefined) {
175	            gameDays = await gameDayService.getAll();
176	        } else {
177	            gameDays.push(await gameDayService.get(gameDayId));
178	        }
179	
180	        const result = gameDays.map((gameDay) => {
181	            const initialResponseCounts = new Map<string, number>([
182	                ['yes', 0],
183	                ['no', 0],
184	                ['dunno', 0],
185	                ['excused', 0],
186	                ['flaked', 0],
187	                ['injured', 0],
188	            ]);
189	            const gameDayResponseCounts = PlayerResponseSchema.options.reduce(
190	                (map, response) => {
191	                    const count =
192	                        responseCounts
193	                            .filter(
194	                                (res) =>
195	                                    res.gameDayId === gameDay?.id &&
196	                                    res.response === `${response}`,
197	                            )
198	                            .map((res) => res._count.response)[0] || 0;
199	                    map.set(`${response.toLowerCase()}`, count);
200	                    return map;
201	                },
202	                initialResponseCounts,
203	            );
204	
205	            if (gameDay) {
206	                return {
207	                    ...gameDay,
208	                    game: isGame(gameDay.status),
209	                    yes: gameDayResponseCounts.get('yes'),
210	                    no: gameDayResponseCounts.get('no'),
211	                    dunno: gameDayResponseCounts.get('dunno'),
212	                    excused: gameDayResponseCounts.get('excused'),
213	                    flaked: gameDayResponseCounts.get('flaked'),
214	                    injured: gameDayResponseCounts.get('injured'),
215	                    responses: responseCounts
216	                        .filter(
217	                            (rc) =>
218	                                rc.gameDayId === gameDay.id &&
219	                                rc.response !== null,
220	                        )
221	                        .reduce((acc, rc) => acc + rc._count.response, 0),
222	                    players:
223	                        responseCounts
224	                            .filter(
225	                                (rc) =>
226	                                    rc.gameDayId === gameDay.id &&
227	                                    rc.response ===
228	                                        PlayerResponseSchema.enum.Yes,
229	                            )
230	                            .map((rc) => rc._count.team)[0] || 0,
231	                    cancelled:
232	                        gameDay.mailSent !== null &&
233	                        gameDay.status === 'NoGame',
234	                };
235	            }
236	        });
237	
238	        return result as Turnout[];
239	    }
240	
241	    /**
242	     * Retrieves the turnout data by year.
243	     * @returns A promise that resolves to an array of `TurnoutByYear` objects.
244	     * @throws If there is an error fetching the outcomes.
245	     */
246	    async getTurnoutByYear(): Promise<TurnoutByYearType[]> {
247	        const turnout = await this.getTurnout();
248	        const gameYears = await gameDayService.getAllYears({});
249	
250	        return gameYears.map((gameYear) => {
251	            const yearTurnout = turnout.filter((t) => gameYear === t.year);
252	            const result: TurnoutByYearType = {
253	                year: gameYear,
254	                gameDays: yearTurnout.length,
255	                gamesScheduled: yearTurnout.filter((t) => t.game || t.mailSent)
256	                    .length,
257	                gamesInitiated: yearTurnout.filter((t) => t.mailSent).length,
258	                gamesPlayed: yearTurnout.filter((t) => t.game && t.mailSent)
259	                    .length,
260	                gamesCancelled: yearTurnout.filter((t) => t.cancelled).length,
261	                responses: yearTurnout.reduce((acc, t) => acc + t.responses, 0),
262	                yesses: yearTurnout.reduce((acc, t) => acc + t.yes, 0),
263	                players: yearTurnout.reduce((acc, t) => acc + t.players, 0),
264	                responsesPerGameInitiated: 0,
265	                yessesPerGameInitiated: 0,
266	                playersPerGamePlayed: 0,
267	            };
268	
269	            if (result.gamesInitiated > 0) {
270	                result.responsesPerGameInitiated = parseFloat(
271	                    (result.responses / result.gamesInitiated).toFixed(1),
272	                );
273	                result.yessesPerGameInitiated = parseFloat(
274	                    (result.yesses / result.gamesInitiated).toFixed(1),
275	                );
276	            }
277	            if (result.gamesPlayed > 0) {
278	                result.playersPerGamePlayed = parseFloat(
279	                    (result.players / result.gamesPlayed).toFixed(1),
280	                );
281	            }
282	
283	            return result;
284	        });
285	    }
286	
287	    /**
288	     * Retrieves outcomes by game day ID and, optionally, team.
289	     * @param gameDayId - The ID of the game day.
290	     * @param team - Optional team ('A' or 'B').
291	     * @returns A promise that resolves to an array of Outcome objects.
292	     * @throws If there is an error fetching the outcomes.
293	     */
294	    async getByGameDay(
295	        gameDayId: number,
296	        team?: 'A' | 'B',
297	    ): Promise<OutcomePlayerType[]> {
298	        const outcomes = await prisma.outcome.findMany({
299	            where: {
300	                gameDayId,
301	                team,
302	            },
303	            include: {
304	                player: true,
305	                gameDay: { select: { status: true } },
306	            },
307	        });
308	
309	        return outcomes.map(({ gameDay, ...outcome }) => ({
310	            ...outcome,
311	            points: getPlayerPoints(gameDay.status, outcome.team),
312	        }));
313	    }
314	
315	    /**
316	     * Retrieves admin response rows for a game day, including active players
317	     * who do not yet have an Outcome for that game day.
318	     * @param gameDayId - The ID of the game day.
319	     * @returns A promise that resolves to one row per active player.
320	     * @throws If there is an error fetching the data.
321	     */
322	    async getAdminByGameDay(gameDayId: number): Promise<OutcomePlayerType[]> {
323	        const validatedGameDayId = z.number().int().min(1).parse(gameDayId);
324	
325	        const [gameDay, activePlayers] = await Promise.all([
326	            gameDayService.get(validatedGameDayId),
327	            prisma.player.findMany({
328	                where: {
329	                    finished: null,
330	                },
331	                orderBy: [{ name: 'asc' }, { id: 'asc' }],
332	                include: {
333	                    outcomes: {
334	                        where: {
335	                            gameDayId: validatedGameDayId,
336	                        },
337	                        take: 1,
338	                    },
339	                },
340	            }),
341	        ]);
342	        const status = gameDay?.status ?? 'NoGame';
343	
344	        return activePlayers.map(({ outcomes, ...player }) => {
345	            const outcome = outcomes[0];
346	            if (outcome) {
347	                return OutcomePlayerType.parse({
348	                    ...outcome,
349	                    points: getPlayerPoints(status, outcome.team),
350	                    player,
351	                });
352	            }
353	
354	            return OutcomePlayerType.parse({
355	                id: -player.id,
356	                gameDayId: validatedGameDayId,
357	                playerId: player.id,
358	                response: null,
359	                responseInterval: null,
360	                points: null,
361	                team: null,
362	                comment: null,
363	                pub: null,
364	                goalie: null,
365	                player,
366	            });
367	        });
368	    }
369	
370	    /**
371	     * Retrieves all players on a given team for a specific game day, including
372	     * their outcome for that day and their recent form.
373	     * @param gameDayId - The game day identifier.
374	     * @param team - Team to fetch ('A' or 'B').
375	     * @param formHistory - Number of previous games to include in each
376	     * player's form graph (default 5, minimum 0).
377	     *
378	     * Form behavior:
379	     * - Uses only prior outcomes with a team assigned on a decided game day.
380	     * - Prior outcomes are returned oldest → newest.
381	     * - If fewer than formHistory outcomes exist, form is left-padded with
382	     *   unplayed sentinel entries (gameDayId: 0, points: null) so the result
383	     *   is always formHistory entries long.
384	     *
385	     * Sorting behavior:
386	     * - Players are ordered with goalies first.
387	     * - Within each group, players are ordered alphabetically by name.
388	     * @returns A promise resolving to the enriched player records.
389	     * @throws If there is an error fetching the data.
390	     */
391	    async getTeamPlayersByGameDay(
392	        gameDayId: number,
393	        team: TeamName,
394	        formHistory = 5,
395	    ): Promise<TeamPlayerType[]> {
396	        const validatedGameDayId = z.number().int().min(1).parse(gameDayId);
397	        const validatedTeam = TeamNameSchema.parse(team);
398	        const validatedHistory = z.number().int().min(0).parse(formHistory);
399	
400	        const outcomes = await prisma.outcome.findMany({
401	            where: {
402	                gameDayId: validatedGameDayId,
403	                team: validatedTeam,
404	            },
405	            include: {
406	                gameDay: true,
407	                player: {
408	                    include: {
409	                        outcomes: {
410	                            where: {
411	                                gameDayId: { lt: validatedGameDayId },
412	                                team: { not: null },
413	                                gameDay: {
414	                                    status: { in: ['AWin', 'BWin', 'Draw'] },
415	                                },
416	                            },
417	                            orderBy: { gameDayId: 'desc' },
418	                            take: validatedHistory,
419	                            include: { gameDay: true },
420	                        },
421	                    },
422	                },
423	            },
424	            orderBy: [{ goalie: 'desc' }, { player: { name: 'asc' } }],
425	        });
426	
427	        return outcomes.map(({ player, gameDay, ...outcome }) => {
428	            if (!player) {
429	                throw new InternalError(
430	                    `Outcome ${outcome.id} is missing its player relation.`,
431	                    {
432	                        details: {
433	                            outcomeId: outcome.id,
434	                            gameDayId: outcome.gameDayId,
435	                            playerId: outcome.playerId,
436	                            team: outcome.team,
437	                        },
438	                    },
439	                );
440	            }
441	            const { outcomes: playerOutcomes = [], ...playerData } = player;
442	
443	            // Outcomes arrive newest-first; reverse so the arc reads oldest→newest.
444	            const actualForm = [...playerOutcomes]
445	                .reverse()
446	                .map(({ gameDay: formGameDay, ...formOutcome }) => ({
447	                    ...formOutcome,
448	                    gameDay: formGameDay,
449	                    points: getPlayerPoints(
450	                        formGameDay.status,
451	                        formOutcome.team,
452	                    ),
453	                }));
454	
455	            // Left-pad with unplayed sentinels for players newer than formHistory games.
456	            const paddingCount = Math.max(
457	                0,
458	                validatedHistory - actualForm.length,
459	            );
460	            const padding = Array.from({ length: paddingCount }, () => ({
461	                id: 0,
462	                gameDayId: 0,
463	                playerId: playerData.id,
464	                response: null,
465	                responseInterval: null,
466	                points: null,
467	                team: null,
468	                comment: null,
469	                pub: null,
470	                goalie: null,
471	            }));
472	
473	            return TeamPlayerSchema.parse({
474	                ...playerData,
475	                outcome: {
476	                    ...outcome,
477	                    points: getPlayerPoints(gameDay.status, outcome.team),
478	                },
479	                form: [...padding, ...actualForm],
480	            });
481	        });
482	    }
483	
484	    /**
485	     * Retrieves outcomes by player ID.
486	     * @param playerId - The ID of the player.
487	     * @returns A promise that resolves to an array of outcomes.
488	     * @throws An error if there is a failure.
489	     */
490	    async getByPlayer(
491	        playerId: number,
492	    ): Promise<(OutcomeType & { points: PointsValue | null })[]> {
493	        const outcomes = await prisma.outcome.findMany({
494	            where: {
495	                playerId: playerId,
496	            },
497	            include: {
498	                gameDay: { select: { status: true } },
499	            },
500	        });
501	
502	        return outcomes.map(({ gameDay, ...outcome }) => ({
503	            ...outcome,
504	            points: getPlayerPoints(gameDay.status, outcome.team),
505	        }));
506	    }
507	
508	    /**
509	     * Retrieves all outcomes for a player across a given year, or all time when
510	     * year is 0. Also includes game days where the player had no outcome
511	     * (not invited) and scheduled days where no game took place
512	     * (status = NoGame) as synthetic entries with null points, so the result
513	     * is suitable for building a full activity heatmap with no gaps.
514	     *
515	     * @param playerId - The ID of the player.
516	     * @param year - The year to filter by, or 0 for all time.
517	     * @param fromDate - Optional earliest date (inclusive). Game days before
518	     * this date are excluded. Useful for filtering to a player's joined date.
519	     * @param toDate - Optional latest date (inclusive). Game days after this
520	     * date are excluded. Useful for filtering to a player's finished date.
521	     * @returns A promise that resolves to outcomes with game days, ordered by
522	     * game day date ascending, with game day ID as a tiebreaker. No-game days
523	     * and uninvited game days are represented as synthetic entries with
524	     * points = null; no-game days have gameDay.status = NoGame.
525	     */
526	    async getHistoryByPlayer(
527	        playerId: number,
528	        year: number,
529	        fromDate?: Date,
530	        toDate?: Date,
531	    ): Promise<PlayerFormType[]> {
532	        const {
533	            playerId: pid,
534	            year: yr,
535	            fromDate: from,
536	            toDate: to,
537	        } = z
538	            .object({
539	                playerId: z.number().int().min(1),
540	                year: z.union([
541	                    z.literal(0),
542	                    z.number().int().min(1900).max(2100),
543	                ]),
544	                fromDate: z.date().optional(),
545	                toDate: z.date().optional(),
546	            })
547	            .parse({ playerId, year, fromDate, toDate });
548	
549	        // All day-boundary arithmetic uses UTC midnight so results are stable
550	        // across timezones and DST transitions.
551	        const utcDay = (y: number, m: number, d: number) =>
552	            new Date(Date.UTC(y, m, d));
553	        const utcDayOf = (date: Date) =>
554	            utcDay(
555	                date.getUTCFullYear(),
556	                date.getUTCMonth(),
557	                date.getUTCDate(),
558	            );
559	        const utcNextDayOf = (date: Date) =>
560	            utcDay(
561	                date.getUTCFullYear(),
562	                date.getUTCMonth(),
563	                date.getUTCDate() + 1,
564	            );
565	
566	        const yearStart = yr > 0 ? utcDay(yr, 0, 1) : undefined;
567	        // When both bounds are present, take the later start so neither is silently ignored.
568	        const startDate =
569	            yearStart && from
570	                ? new Date(
571	                      Math.max(yearStart.getTime(), utcDayOf(from).getTime()),
572	                  )
573	                : (yearStart ?? (from ? utcDayOf(from) : undefined));
574	        const yearEnd = yr > 0 ? utcDay(yr + 1, 0, 1) : undefined;
575	        // For toDate, convert the inclusive finished date to an exclusive upper bound (next UTC day),
576	        // then take the earliest of the year end, player finish, and tomorrow (no future game days).
577	        const finishedEnd = to ? utcNextDayOf(to) : undefined;
578	        const tomorrow = utcNextDayOf(new Date());
579	        const candidates = [yearEnd, finishedEnd, tomorrow].filter(
580	            (d): d is Date => d !== undefined,
581	        );
582	        const endDate = new Date(
583	            Math.min(...candidates.map((d) => d.getTime())),
584	        );
585	        // endDate is always defined: candidates always contains tomorrow.
586	        const dateRange: { gte?: Date; lt: Date } = { lt: endDate };
587	        if (startDate) dateRange.gte = startDate;
588	        const dateFilter = { date: dateRange };
589	
