async getByGameDay(
    gameDayId: number,
    team?: 'A' | 'B',
): Promise<OutcomePlayerType[]> {
    const [outcomes, playerRecords] = await Promise.all([
        prisma.outcome.findMany({
            where: {
                gameDayId,
                team,
            },
            include: {
                player: true,
            },
        }),
        prisma.playerRecord.findMany({
