        (prisma.player.findMany as Mock).mockResolvedValueOnce([
            playerWithNoOutcomes,
        ]);

        const result = await playerService.getAll();
        expect(result).toHaveLength(1);
        expect(result[0].firstResponded).toBeNull();
        expect(result[0].lastResponded).toBeNull();
        expect(result[0].firstPlayed).toBeNull();
        expect(result[0].lastPlayed).toBeNull();
        expect(result[0].gamesPlayed).toBe(0);
    });

    it('should anonymise names in list responses when players are anonymous', async () => {
        const anonymousPlayer: PlayerType & {
            outcomes: OutcomeType[];
            extraEmails: PlayerExtraEmailType[];
        } = {
            ...defaultPlayer,
            id: 1,
            name: 'Should Not Leak',
            anonymous: true,
            extraEmails: [],
            outcomes: [],
        };

        (prisma.player.findMany as Mock).mockResolvedValueOnce([
            anonymousPlayer,
        ]);

        const result = await playerService.getAll();
        expect(result[0].name).toBe('Player 1');
    });

    it('should pass a finished:null filter when activeOnly is true', async () => {
        (prisma.player.findMany as Mock).mockResolvedValueOnce([]);
        await playerService.getAll({ activeOnly: true });
        expect(prisma.player.findMany).toHaveBeenCalledWith(
            expect.objectContaining({ where: { finished: null } }),
        );
    });

    it('normalises a missing accountEmail to null', async () => {
        (prisma.player.findMany as Mock).mockResolvedValueOnce([
            {
                ...defaultPlayer,
                id: 3,
                accountEmail: undefined,
                extraEmails: [],
                outcomes: [],
            },
        ]);
        const result = await playerService.getAll();
        expect(result[0].accountEmail).toBeNull();
    });

    it('maps a non-null verifiedAt to verified: true', async () => {
        (prisma.player.findMany as Mock).mockResolvedValueOnce([
            {
                ...defaultPlayer,
                id: 1,
                extraEmails: [
                    {
                        id: 1,
                        playerId: 1,
                        email: 'extra@example.com',
                        verifiedAt: new Date('2024-01-01'),
                        createdAt: new Date('2024-01-01'),
                    },
                ],
                outcomes: [],
            },
        ]);
        const result = await playerService.getAll();
        expect(result[0].extraEmails).toEqual([
            { email: 'extra@example.com', verified: true },
        ]);
    });

    it('maps a null verifiedAt to verified: false', async () => {
        (prisma.player.findMany as Mock).mockResolvedValueOnce([
            {
                ...defaultPlayer,
                id: 1,
                extraEmails: [
                    {
                        id: 1,
                        playerId: 1,
                        email: 'pending@example.com',
                        verifiedAt: null,
                        createdAt: new Date('2024-01-01'),
                    },
                ],
                outcomes: [],
            },
        ]);
        const result = await playerService.getAll();
        expect(result[0].extraEmails).toEqual([
            { email: 'pending@example.com', verified: false },
        ]);
    });

    it('preserves the order of extraEmails as returned by Prisma', async () => {
        (prisma.player.findMany as Mock).mockResolvedValueOnce([
            {
                ...defaultPlayer,
                id: 1,
                extraEmails: [
                    {
                        id: 2,
                        playerId: 1,
                        email: 'verified@example.com',
                        verifiedAt: new Date('2024-06-01'),
                        createdAt: new Date('2024-01-01'),
                    },
                    {
                        id: 1,
                        playerId: 1,
                        email: 'unverified@example.com',
                        verifiedAt: null,
                        createdAt: new Date('2024-05-01'),
                    },
                ],
                outcomes: [],
            },
        ]);
        const result = await playerService.getAll();
        expect(result[0].extraEmails).toEqual([
            { email: 'verified@example.com', verified: true },
            { email: 'unverified@example.com', verified: false },
        ]);
    });

    it('returns empty extraEmails when extraEmails is undefined', async () => {
        (prisma.player.findMany as Mock).mockResolvedValueOnce([
            {
                ...defaultPlayer,
                id: 1,
                extraEmails: undefined,
                outcomes: [],
            },
        ]);
        const result = await playerService.getAll();
        expect(result[0].extraEmails).toEqual([]);
    });

    it('passes the correct include with extraEmails select and orderBy to Prisma', async () => {
        (prisma.player.findMany as Mock).mockResolvedValueOnce([]);
        await playerService.getAll();
        expect(prisma.player.findMany).toHaveBeenCalledWith({
            include: {
                extraEmails: {
                    select: { email: true, verifiedAt: true },
                    orderBy: [
                        { verifiedAt: 'desc' },
                        { createdAt: 'desc' },
                    ],
                },
                outcomes: {
                    orderBy: {
                        gameDayId: 'desc',
                    },
                    include: {
                        gameDay: { select: { status: true } },
                    },
                },
            },
            where: undefined,
        });
    });
});

