    return (
        <>
            <AutoRefresh channels={FootyChannel.Games} />
            <DrinkersForm
                gameId={gameDay.id}
                gameDate={formatDate(gameDay.date)}
                players={players}
                setDrinkers={setDrinkers}
                previousGameId={previousGame?.id}
                nextGameId={nextGame?.id}
            />
        </>
    );
};

export default DrinkersPage;
