        expect(result).toEqual(
            fixture.map((outcome) => ({
                ...outcome,
                points: 3,
            })),
        );
    });

    it('should return an empty list when retrieving outcomes for GameDay id 101', async () => {
        (prisma.outcome.findMany as Mock).mockResolvedValueOnce([]);
