        const result = await outcomeService.getByGameDay(101);
        expect(prisma.outcome.findMany).toHaveBeenCalledWith({
            where: { gameDayId: 101, team: undefined },
            include: {
                player: true,
            },
        });
        expect(result).toEqual([]);
    });
});

